/**
 * Live EEG stream.
 * ⚠️ MOCK: when USE_MOCKS === true, snapshots are generated by ./mocks/brain.mock.ts every 250 ms.
 * Real backend: FastAPI sends successive electrode readings via `yield`
 * (SSE by default) or over WebSocket (VITE_EEG_TRANSPORT=ws).
 */
import type { EegStreamInput } from "@/types/api/input/useEeg";
import type { EegStreamMessage, EegTransport } from "@/types/api/output/useEeg";
import { connectSse } from "@/lib/realtime/sse";
import { connectWs } from "@/lib/realtime/ws";
import type { StreamCallbacks, StreamHandle } from "@/lib/realtime/types";
import { API_BASE_URL, USE_MOCKS } from "./client";
import { mockBrainSnapshot } from "./mocks/brain.mock";

export const EEG_TRANSPORT: EegTransport = USE_MOCKS ? "mock" : (import.meta.env.VITE_EEG_TRANSPORT ?? "sse");

const MOCK_INTERVAL_MS = 250;

export function subscribeEegStream(input: EegStreamInput, cb: StreamCallbacks<EegStreamMessage>): StreamHandle {
  const q = input.sessionId ? `?session_id=${encodeURIComponent(input.sessionId)}` : "";

  if (EEG_TRANSPORT === "sse") return connectSse(`${API_BASE_URL}/api/eeg/stream${q}`, cb);
  if (EEG_TRANSPORT === "ws") return connectWs(`${API_BASE_URL.replace(/^http/, "ws")}/ws/eeg/live${q}`, cb);

  // --- MOCK --- pretending to be the backend stream
  cb.onStatus?.("open");
  const id = window.setInterval(() => cb.onMessage(mockBrainSnapshot()), MOCK_INTERVAL_MS);
  return {
    close: () => {
      window.clearInterval(id);
      cb.onStatus?.("closed");
    },
  };
}
